sn_aia_tool.script:
(function(inputs) {
    // only string inputs are allowed 
    // return outputs object where the keys in it are understandable by LLM
    var skippedSummary = [];
    var priority = '';
    var count = 0;
    var upgradeLogAgg = new GlideAggregate('sys_upgrade_history_log');
    upgradeLogAgg.addEncodedQuery("upgrade_history=" + inputs.upgradeID.toString() + "^resolution_status=not_reviewed");
    upgradeLogAgg.addAggregate('COUNT');
    upgradeLogAgg.groupBy('type_priority');
    upgradeLogAgg.orderBy('type_priority');
    upgradeLogAgg.query();

    while (upgradeLogAgg.next()) {
        priority = upgradeLogAgg.getDisplayValue('type_priority') || '(empty)';
        count = upgradeLogAgg.getAggregate('COUNT');
        skippedSummary.push({
            "priority": priority,
            "record_count": count
        });
    }
    return JSON.stringify(skippedSummary);
})(inputs);
